var TUNE={startDelay:600,lead:900,press:300,dwell:2400,hold:2500,nextPrompt:1400,watch:'Watching',turn:'Your turn',done:'Done'};
var mode='watch',cur=0,watchOn=false;
var bar=document.createElement('div');bar.className='tbar';
